import datetime
import calendar

def next_billing_date(start: datetime.date, months_ahead: int) -> datetime.date:
    if months_ahead < 0:
        raise ValueError("months_ahead must be non-negative")
    new_month = start.month + months_ahead
    new_year = start.year + (new_month - 1) // 12
    new_month = (new_month - 1) % 12 + 1
    day = start.day
    try:
        return datetime.date(new_year, new_month, day)
    except ValueError:
        last_day = calendar.monthrange(new_year, new_month)[1]
        return datetime.date(new_year, new_month, last_day)
